Events.get = async (tid, uid) => {
	const topics = require('.');

	if (!await topics.exists(tid)) {
		throw new Error('[[error:no-topic]]');
	}

	let eventRecords = await db.getSortedSetRangeWithScores(`topic:${tid}:events`, 0, -1);
	const allEvents = await db.getObjects(eventRecords.map(obj => `topicEvent:${obj.value}`));
	if (!meta.config.topicBacklinks) {
		eventRecords = eventRecords.filter((record, index) => allEvents[index] && allEvents[index].type !== 'backlink');
	}
	const eventIds = eventRecords.map(obj => obj.value);
	const timestamps = eventRecords.map(obj => obj.score);
	let events = eventRecords.map(record => allEvents.find((event, index) => event && String(eventRecords[index].value) === String(record.value)));
	events = await modifyEvent({ tid, uid, eventIds, timestamps, events });

	return events;
};

